popup.command:
import maya.cmds as cmds
for cam in ('perspShape', 'frontShape', 'sideShape', 'topShape'):
    if cmds.objExists(cam):
        cmds.setAttr(f'{cam}.nearClipPlane', 1.0)
        cmds.setAttr(f'{cam}.farClipPlane', 1000000.0)

import maya.cmds as cmds, os, importlib
import maya_tools.skinning.skin_io.skin_io_app as a; importlib.reload(a)
path = os.path.join(cmds.internalVar(userAppDir=True), 'am_skin_temp.json')
meshes = [s for s in (cmds.ls(sl=True, type='transform') or []) if cmds.listRelatives(s, s=True, type='mesh', noIntermediate=True)]
if not meshes:
    cmds.warning('Select at least one mesh to save temp skin.')
else:
    a.save_skin_from_meshes(meshes, path)
    cmds.inViewMessage(msg='Saved temp skin from ' + str(len(meshes)) + ' mesh(es)', pos='midCenter', fade=True)

import maya.cmds as cmds, os, importlib
import maya_tools.skinning.skin_io.skin_io_app as a; importlib.reload(a)
path = os.path.join(cmds.internalVar(userAppDir=True), 'am_skin_temp.json')
if not os.path.exists(path):
    cmds.warning('No temp skin file found. Run Save Temp first.')
else:
    meshes = [s for s in (cmds.ls(sl=True, type='transform') or []) if cmds.listRelatives(s, s=True, type='mesh', noIntermediate=True)]
    if not meshes: cmds.warning('Select at least one mesh.')
    else:
        a.load_skin_to_meshes(meshes, path, mode='direct')
        cmds.inViewMessage(msg='Loaded temp skin (direct) onto ' + str(len(meshes)) + ' mesh(es)', pos='midCenter', fade=True)

